<?php
declare(strict_types=1);
require dirname(__DIR__,2).'/bootstrap.php';
use App\Core\Auth;use App\Core\Database;use App\Services\DanceCupScoringService;
Auth::requireAdmin();$test=(string)($_GET['data_mode']??'')==='test';if($test&&!Auth::isSuperAdmin()){http_response_code(403);exit('Super Admin access required.');}$workflow=(string)($_GET['workflow']??'');
$modes=['manual'=>['Manual Scoring','category.php','Open','dark','✎','Create and score categories entirely in the Manual workflow.'],'automatic'=>['Automatic Scoring','automatic-setup.php','Open','primary','⚙','Manage each event and all its secure judge-link categories in one place.'],'projection'=>['Live Projection','projection-control.php','Open','danger','▣','Control the audience screen for any Dance Cup category.']];
if(!isset($modes[$workflow])){header('Location: ./'.($test?'?data_mode=test':''),true,303);exit;}
$pdo=Database::connection();DanceCupScoringService::ensureWorkspaceTables($pdo,$test);$tables=DanceCupScoringService::tables($test);$sql="SELECT c.id,c.event_id,c.category_name,c.dance_style,c.competition_level,c.entry_type,c.round_name,c.status,c.scoring_mode,e.name event_name,e.event_date,e.end_date,e.venue,e.country FROM {$tables['competitions']} c JOIN {$tables['events']} e ON e.id=c.event_id WHERE e.status<>'archived'";$params=[];if($workflow!=='projection'){$sql.=" AND c.scoring_mode=:mode";$params['mode']=$workflow;}$sql.=" ORDER BY e.event_date DESC,e.id DESC,c.category_name,c.id";$query=$pdo->prepare($sql);$query->execute($params);$categories=$query->fetchAll();$events=[];foreach($categories as $category){$eventId=(int)$category['event_id'];if(!isset($events[$eventId]))$events[$eventId]=['id'=>$eventId,'name'=>$category['event_name'],'event_date'=>$category['event_date'],'end_date'=>$category['end_date'],'venue'=>$category['venue'],'country'=>$category['country'],'categories'=>[]];$events[$eventId]['categories'][]=$category;}
[$label,$route,$actionLabel,$colour,$icon,$description]=$modes[$workflow];$suffix=$test?'&data_mode=test':'';$creationWorkflow=$workflow==='projection'?'manual':$workflow;
