-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:700px){.workflow-hero{border-radius:18px}.event-head{align-items:flex-start;padding:18px}.event-title{font-size:1.12rem}.event-count{min-width:76px}.category-grid{grid-template-columns:1fr;padding:12px}.category-card h3{min-height:0}.category-actions{grid-template-columns:1fr 1fr}.category-actions .btn:first-child{grid-column:1/-1}.top-actions{width:100%}.top-actions .btn{flex:1 1 auto}}
