<div class="d-flex justify-content-between align-items-center gap-3 flex-wrap mb-3"><div><div class="event-kicker">EVENT WORKSPACE</div><h2 class="h4 mb-0">Events &amp; Categories</h2></div><div class="top-actions"><?php if($workflow==='automatic'):?><a class="btn btn-primary" href="panels.php<?=$test?'?data_mode=test':''?>">Judging Panels</a><?php endif;?><a class="btn btn-outline-secondary" href="./<?=$test?'?data_mode=test':''?>">← Scoring Options</a><a class="btn btn-warning" href="index.php?workflow=<?=e($creationWorkflow)?><?=$suffix?>"><?=$workflow==='projection'?'Manage Events & Categories':'Create Event / Category'?></a></div></div>
<?php foreach($events as $event):?><section class="event-section mb-4" data-event-id="<?=(int)$event['id']?>"><header class="event-head"><div><div class="event-kicker">Dance Cup Event</div><h2 class="event-title"><?=e($event['name'])?></h2><div class="event-meta"><?php if($event['event_date']):?><span>📅 <?=e(date('d M Y',strtotime((string)$event['event_date'])))?><?php if($event['end_date']&&$event['end_date']!==$event['event_date']):?> – <?=e(date('d M Y',strtotime((string)$event['end_date'])))?><?php endif;?></span><?php endif;?><?php if($event['venue']):?><span>⌖ <?=e($event['venue'])?></span><?php endif;?><?php if($event['country']):?><span><?=e($event['country'])?></span><?php endif;?></div></div><div class="event-count"><strong><?=count($event['categories'])?></strong><small><?=count($event['categories'])===1?'Category':'Categories'?></small></div></header><div class="category-grid">
<?php foreach($event['categories'] as $category):?><article class="card category-card h-100"><div class="card-body d-flex flex-column"><h3 class="h5"><?=e($category['category_name'])?></h3><div class="meta mb-4"><span><?=e(ucwords(str_replace('_',' ',$category['dance_style'])))?></span><span><?=e(ucwords(str_replace('_',' ',$category['competition_level'])))?></span><span><?=e(ucwords(str_replace('_',' ',$category['entry_type'])))?></span><span><?=e(ucfirst($category['round_name']))?></span><span><?=e(ucfirst($category['status']))?></span><?php if($workflow==='projection'):?><span><?=e(ucfirst($category['scoring_mode']))?> scoring</span><?php endif;?></div><div class="category-actions"><a class="btn btn-<?=e($colour)?>" href="<?=e($route)?>?id=<?=(int)$category['id']?><?=$suffix?>"><?=e($actionLabel)?></a><?php if($workflow!=='projection'):?><a class="btn btn-outline-warning" href="category-edit.php?id=<?=(int)$category['id']?><?=$suffix?>">Edit</a><?php endif;?><?php if($workflow!=='projection'&&$category['status']==='draft'):?><a class="btn btn-outline-danger" href="delete-draft.php?id=<?=(int)$category['id']?><?=$suffix?>">Delete</a><?php endif;?></div></div></article><?php endforeach;?></div></section><?php endforeach;?>
<?php if(!$events):?><section class="empty-state text-center p-5"><h3 class="h5">No events in this workflow</h3><p class="text-muted">Create an event and its first category. Future categories will stay grouped under that event here.</p><a class="btn btn-warning" href="index.php?workflow=<?=e($creationWorkflow)?><?=$suffix?>">Create Event / Category</a></section><?php endif;?></main></body></html>
